/**
 * 204 product seed documents across all 21 categories.
 * Import into any seed runner; do NOT import into browser bundles.
 */

import { VENDOR_IDS, VENDOR_NAMES, type VendorKey } from "./ids";
import { productImages, toSlug } from "./utils";
import { CATEGORY_NAME_MAP } from "@/constants";

// All raw prices are in GBP. Multiply by this rate to store as INR.
const GBP_TO_INR = 106;
function toINR(gbp: number): number { return Math.round(gbp * GBP_TO_INR); }

export interface ProductSeed {
  name: string;
  slug: string;
  description: string;
  price: number;
  originalPrice?: number;
  images: string[];
  category: string;
  brand: string;
  unit: string;
  inStock: boolean;
  rating: number;
  reviewCount: number;
  tags: string[];
  badge?: "NEW" | "HOT" | "LIMITED" | "ORGANIC" | "EXCLUSIVE" | null;
  vendorId?: string;
  vendorName?: string;
}

type RawRow = {
  n: string;
  c: string;
  b: string;
  p: number;
  o?: number;
  u: string;
  t: string[];
  bg?: "NEW" | "HOT" | "LIMITED" | "ORGANIC" | "EXCLUSIVE";
  vk?: VendorKey;
  d: string;
  r: number;
  rc: number;
  oos?: boolean;
};

function expand(row: RawRow): ProductSeed {
  return {
    name:          row.n,
    slug:          toSlug(row.n),
    description:   row.d,
    price:         toINR(row.p),
    ...(row.o ? { originalPrice: toINR(row.o) } : {}),
    images:        productImages(row.n, row.c),
    category:      CATEGORY_NAME_MAP[row.c] ?? row.c,
    brand:         row.b,
    unit:          row.u,
    inStock:       !row.oos,
    rating:        row.r,
    reviewCount:   row.rc,
    tags:          row.t,
    badge:         row.bg ?? null,
    ...(row.vk
      ? { vendorId: VENDOR_IDS[row.vk], vendorName: VENDOR_NAMES[row.vk] }
      : {}),
  };
}

